import icontract
from typing import List


@icontract.ensure(lambda x, result: result == all(x[i] == x[len(x) - i - 1] for i in range(len(x))))
def IsPalindrome(x: List[str]) -> bool:
    i, j = 0, len(x) - 1
    while i < j:
        if x[i] != x[j]:
            return False
        i += 1
        j -= 1
    return True
